// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address from = address(0x1);
        address caddress = address(0x2);
        address[] memory _tos = new address[](1);
        _tos[0] = address(0x3);
        uint[] memory v = new uint[](1);
        v[0] = 100;
        // For this test, we cannot observe the transferFrom call on an arbitrary address;
        // instead we rely on the fact that the reference contract will revert on the first
        // iteration (since caddress is a random non-contract address that will fail the call)
        // while the buggy contract will skip the iteration and return true.
        bool ok;
        try c.transfer(from, caddress, _tos, v) {
            ok = true;
        } catch {
            ok = false;
        }
        // The reference reverts because it tries to call transferFrom on a non-contract.
        // The buggy version (start i=1) skips the loop entirely, returns true.
        // This assertion holds for the reference (ok=false) and fails for the buggy version (ok=true).
        assertTrue(ok == false);
    }
}

