pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a minimal ERC20-like token that tracks total transfers via a counter
        // For simplicity, use a separate helper that can be called via call
        // Instead, use a simple token that reverts if transferFrom is not called properly
        // We'll use a mock that records calls
        address token = address(new MockToken());

        address from = address(0x123);
        address[] memory tos = new address[](2);
        tos[0] = address(0x456);
        tos[1] = address(0x789);
        uint[] memory amounts = new uint[](2);
        amounts[0] = 100;
        amounts[1] = 200;

        // Call transfer on the contract
        bool success = c.transfer(from, token, tos, amounts);
        require(success, "transfer failed");

        // The reference calls transferFrom for tos[0] and tos[1], so callCount should be 2
        uint256 callCount = MockToken(token).callCount();
        assertTrue(callCount == 2, "expected callCount to be 2 for reference, but bug may produce 1");
    }
}

contract MockToken {
    uint256 public callCount;
    function transferFrom(address, address, uint256) external returns (bool) {
        callCount++;
        return true;
    }
}

